    E -- random index --> E1[ArrayList]
    E -- queue / deque --> E2[ArrayDeque]
    D -- no --> F{Order of set?}
    F -- none --> F1[HashSet]
    F -- insertion --> F2[LinkedHashSet]
    F -- sorted --> F3[TreeSet]
